from pathlib import Path
import csv,json,statistics,zipfile
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import xlsxwriter
R=Path(__file__).resolve().parents[1]; A=R/'analysis'; P=R/'plots';P.mkdir(exist_ok=True)
def read(n):
 with (R/n).open(newline='',encoding='utf-8-sig') as f:return list(csv.DictReader(f))
def write(p,fields,rs):
 with p.open('w',newline='',encoding='utf-8') as f:w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rs)
b=read('benchmark_results.csv');u=read('upload_results.csv');d=read('download_results.csv');f=read('fault_tolerance_results.csv');i=read('integrity_verification_results.csv');r=read('replication_results.csv');sizes=sorted({int(x['file_size_bytes']) for x in b});s=[]
for z in sizes:
 U=[float(x['upload_time_ms']) for x in u if int(x['file_size_bytes'])==z];D=[float(x['download_time_ms']) for x in d if int(x['file_size_bytes'])==z];UT=[float(x['throughput_mbps']) for x in u if int(x['file_size_bytes'])==z];DT=[float(x['throughput_mbps']) for x in d if int(x['file_size_bytes'])==z]
 s.append(dict(file_size_bytes=z,trials=len(U),mean_upload_ms=statistics.mean(U),median_upload_ms=statistics.median(U),stdev_upload_ms=statistics.stdev(U),mean_download_ms=statistics.mean(D),median_download_ms=statistics.median(D),stdev_download_ms=statistics.stdev(D),mean_upload_throughput_mbps=statistics.mean(UT),mean_download_throughput_mbps=statistics.mean(DT)))
write(A/'benchmark_summary.csv',list(s[0]),s)
for metric,title,ylabel,file in [('upload','Upload latency by payload size','Mean request latency (ms)','upload_latency_by_size.png'),('download','Download latency by payload size','Mean request latency (ms)','download_latency_by_size.png')]:
 fig,ax=plt.subplots(figsize=(8,4.6));ax.errorbar([x['file_size_bytes']/1048576 for x in s],[x[f'mean_{metric}_ms'] for x in s],yerr=[x[f'stdev_{metric}_ms'] for x in s],marker='o',capsize=4,color='#087E8B');ax.set(title=title,xlabel='File size (MiB)',ylabel=ylabel);ax.grid(alpha=.25);fig.tight_layout();fig.savefig(P/file,dpi=180);plt.close(fig)
fig,ax=plt.subplots(figsize=(8,4.6));ax.plot([x['file_size_bytes']/1048576 for x in s],[x['mean_upload_throughput_mbps'] for x in s],marker='o',label='Upload');ax.plot([x['file_size_bytes']/1048576 for x in s],[x['mean_download_throughput_mbps'] for x in s],marker='o',label='Download');ax.set(title='Effective client-observed throughput',xlabel='File size (MiB)',ylabel='Decimal Mbps');ax.grid(alpha=.25);ax.legend();fig.tight_layout();fig.savefig(P/'throughput_by_size.png',dpi=180);plt.close(fig)
keys=['detection_time_ms','promotion_time_ms','recovery_time_ms'];means=[statistics.mean([float(x[k]) for x in f]) for k in keys];errs=[statistics.stdev([float(x[k]) for x in f]) for k in keys];fig,ax=plt.subplots(figsize=(8,4.6));ax.bar(['Detection','N3 active after DOWN','Total to N3 active'],means,yerr=errs,capsize=4,color=['#087E8B','#F2A541','#2F9E70']);ax.set(title='Controlled N1 failure trials (n=3)',ylabel='Mean elapsed time (ms)');ax.grid(axis='y',alpha=.25);fig.tight_layout();fig.savefig(P/'fault_detection_recovery.png',dpi=180);plt.close(fig)
# Spreadsheet sheets reproduce the measured CSV rows and processed summary.
w=xlsxwriter.Workbook(str(R/'experimental_results.xlsx'));hf=w.add_format({'bold':True,'bg_color':'#DCEAF4','border':1,'text_wrap':True});nf=w.add_format({'num_format':'0.000'})
for name,rs in [('Benchmark',b),('Upload',u),('Download',d),('Fault tolerance',f),('Integrity',i),('Replication',r),('Summary',s)]:
 ws=w.add_worksheet(name)
 if not rs:continue
 cols=list(rs[0]);ws.write_row(0,0,cols,hf)
 for ri,row in enumerate(rs,1):
  for ci,key in enumerate(cols):
   v=row.get(key,'')
   if v=='':ws.write_blank(ri,ci,None)
   elif key.endswith('_ms') or key.endswith('_mbps') or key.startswith('mean_') or key.startswith('median_') or key.startswith('stdev_'):ws.write_number(ri,ci,float(v),nf)
   elif isinstance(v,int):ws.write_number(ri,ci,v)
   else:ws.write(ri,ci,v)
 ws.freeze_panes(1,0);ws.autofilter(0,0,len(rs),len(cols)-1);ws.set_column(0,len(cols)-1,22)
w.close()
# Inventory lists observed inputs, normalized tables, raw records, summaries and figures.
items=[('benchmark_results.csv','12 combined transfer trial rows'),('upload_results.csv','12 upload timing observations'),('download_results.csv','12 download timing observations'),('fault_tolerance_results.csv','3 controlled N1 failure trials'),('integrity_verification_results.csv','1 controlled corruption case'),('replication_results.csv','15 per-file replica-state checks'),('test_file_manifest.csv','4 ephemeral generated payload definitions'),('environment_details.json','Captured runtime and host details'),('experimental_results.xlsx','Workbook of observed and summarized tables'),('analysis/benchmark_summary.csv','Processed means, medians and sample deviations'),('raw_results/upload_retrieval_raw.csv','Repository harness raw output'),('raw_results/failure_recovery_raw.csv','Repository harness raw output'),('raw_results/integrity_probe.json','Raw controlled-corruption evidence'),('plots/upload_latency_by_size.png','Measured upload latency with sample-standard-deviation bars'),('plots/download_latency_by_size.png','Measured download latency with sample-standard-deviation bars'),('plots/throughput_by_size.png','Derived decimal Mbps from observed timings'),('plots/fault_detection_recovery.png','Three observed failure trials with sample-standard-deviation bars')]
write(R/'dataset_inventory.csv',['dataset_id','filename','dataset_type','description','format','source','generation_method','record_count','status'],[dict(dataset_id=f'D{n:02}',filename=x,dataset_type='measured' if n<10 else ('plot' if x.startswith('plots/') else 'raw/processed'),description=desc,format=x.rsplit('.',1)[-1].upper(),source='Isolated local project run' if n<10 else 'Derived/preserved experiment evidence',generation_method='Harness or analysis script; no fabricated values',record_count=(len(b) if x=='benchmark_results.csv' else len(u) if x=='upload_results.csv' else len(d) if x=='download_results.csv' else len(f) if x=='fault_tolerance_results.csv' else len(i) if x=='integrity_verification_results.csv' else len(r) if x=='replication_results.csv' else len(read('test_file_manifest.csv')) if x=='test_file_manifest.csv' else ''),status='observed' if n<10 else 'generated/derived') for n,(x,desc) in enumerate(items,1)])
(R/'README.md').write_text('''# Experimental data package\n\nThis package contains genuine observations from the isolated project run `isolated_project_20261021_000718`. The upload/download harness ran four sizes (102,400; 1,048,576; 5,242,880; 10,485,760 bytes) with three trials each. All 12 uploads and downloads returned successfully and matched the original in-memory payload byte for byte. The controlled N1 failure harness ran three trials. A separate corruption probe altered one encrypted primary chunk only in the isolated copy and verified alternate-replica retrieval.\n\n## Files\n\n`benchmark_results.csv`, `upload_results.csv`, `download_results.csv`, `fault_tolerance_results.csv`, `integrity_verification_results.csv`, and `replication_results.csv` contain observations. `test_file_manifest.csv` documents ephemeral payload generation; payloads were not retained and their original checksums were not captured. `environment_details.json` records known environment information. `experimental_results.xlsx` mirrors the tables. `analysis/benchmark_summary.csv` has means, medians and sample standard deviations. `plots/` contains charts generated only from these measurements. `dataset_inventory.csv` indexes the data. Exact raw harness CSV/JSON output and isolated databases/chunks are under `raw_results/`.\n\n## Measurement definitions\n\nRequest latency is `time.perf_counter()` elapsed around synchronous Python Requests calls to `POST /files` or `GET /files/<file_id>`. Throughput is effective client-observed decimal Mbps: `file_size_bytes × 8 / (elapsed_ms / 1000) / 1,000,000`; it includes HTTP, coordinator, crypto, SQLite, TCP and local scheduling costs and is not link capacity. Each transfer trial is success only after byte-for-byte comparison. Error bars show sample standard deviation across three trials. Failure status was polled every 100 ms, so detection/recovery boundaries are sampling approximations.\n\n## Reproduction and safety\n\nThe repository scripts write to `experiments/results`, delete their named SQLite database files, and node processes write under `node_data`. Run only in a disposable copy after checking ports 5000, 6001–6003 and 6100 are free. The retained copy is under `raw_results/isolated_project_20261021_000718`.\n\n## Evidence and limitations\n\nPost-run inspection confirmed two copies for each of 51 benchmark chunks on N1/N2, with file bytes matching SQLite SHA-256 metadata. Each of three failure runs ended with N1 DOWN, N3 ACTIVE and replicas mapped to N2/N3; chunk files and hashes were checked and retrieved content matched. One corruption case detected the altered N1 chunk and returned original bytes from the alternate N2 copy. The corrupted copy was not repaired. Prior repository audit reported 11 unit tests passed; they were not rerun during this data collection. Runs were on one Windows host via loopback and are not production or multi-host benchmarks. The original harness did not record per-trial UTC timestamps; these fields are blank.\n''',encoding='utf-8')
(R/'methodology.md').write_text('''# Methodology\n\nThree project processes (Flask coordinator and N1–N3) were started in an isolated project copy on localhost. Ports 5000, 6001–6003 and 6100 were confirmed free. `P2P_DB_PATH` directed SQLite to isolated run databases; node chunks stayed in clone-local storage. Verified configuration: 1 MiB chunk size, replication factor 2, heartbeat interval 1 s, timeout 4 s.\n\nFor transfer performance, the harness generated one `os.urandom(size)` payload in memory per size and reused it for three sequential POST/GET trials. Sizes were 100 KiB, 1 MiB, 5 MiB and 10 MiB. `time.perf_counter()` surrounded each HTTP call. A trial passed only if HTTP succeeded and retrieved bytes equaled the payload. Throughput uses decimal Mbps, `bytes × 8 / seconds / 1,000,000`; it is application-level effective throughput. Means, medians, sample standard deviations and trial counts are in `analysis/benchmark_summary.csv`; chart error bars are sample deviations.\n\nReplication was checked by comparing every SQLite replica mapping with the corresponding file on disk and hashing its encrypted bytes against the recorded chunk SHA-256. All 51 chunks in 12 performance files had two valid copies on N1/N2. Failure testing uploaded 16 KiB, terminated only the harness-owned N1 process, then polled `/status` every 100 ms. Detection is termination request to observed N1 DOWN; promotion interval is first observed DOWN to first observed N3 ACTIVE; total recovery is termination to observed N3 ACTIVE. After each test, SQLite rows and both N2/N3 chunk files/hashes were checked and the harness verified downloaded bytes. Three trials passed.\n\nThe integrity test uploaded 4,096 random bytes, flipped one byte in the isolated N1 PRIMARY encrypted chunk, confirmed its hash differed from metadata, then downloaded and compared with original in-memory bytes. Retrieval passed using the alternate replica. Corrupt data remained on N1, so this establishes detection and fallback, not repair. Audit-chain verification was true after download. Raw outputs are preserved under `raw_results/`; normalized measurements and summaries are generated by `analysis/collect_results.py` and `analysis/analyze_results.py`. The 11 previously reported unit tests were not rerun.\n''',encoding='utf-8')
(R/'limitations.md').write_text('''# Limitations\n\n- All services ran on one Windows machine over loopback; results do not characterize a multi-host network.\n- Three repetitions per payload size and three identical N1 failures provide a small sample.\n- Latencies include client, Flask, chunking, encryption, SQLite, TCP and scheduler overhead.\n- The harness omitted per-trial UTC timestamps, resource utilization and input checksums; these are not fabricated.\n- Failure times use 100 ms status polling. A zero sampled promotion interval means state changes appeared in the same polling cycle, not necessarily zero internal work.\n- Only single N1 process termination with a 16 KiB file was tested. Partitions, simultaneous failures, restart/reintegration and sustained load were not tested.\n- Corruption testing showed rejection/fallback retrieval; corrupted replica repair was not observed.\n- Two replicas were verified only for tested chunks; this does not prove general durability or availability. Replication is not a backup.\n- Key-management security, hostile tampering, scalability and production deployment were not evaluated. Unit tests previously reported as 11 passed were not rerun here.\n''',encoding='utf-8')
(A/'README.md').write_text('''# Analysis files\n\n`collect_results.py` normalizes harness measurements and validates SQLite replica mappings against isolated on-disk chunks. `analyze_results.py` calculates summary statistics, writes the XLSX workbook and regenerates plots. Run with the documentation environment Python from the repository root. The only inputs are retained outputs in `raw_results/isolated_project_20261021_000718/experiments/results/`; no synthetic measurements are generated.\n\nPlots: upload latency, download latency, effective throughput, and failure detection/recovery. Error bars represent sample standard deviation where three trials exist.\n''',encoding='utf-8')
(R/'raw_results'/'README.md').write_text('''# Raw results\n\n`upload_retrieval_raw.csv` and `failure_recovery_raw.csv` are direct harness outputs; `integrity_probe.json` is the controlled corruption record. The isolated project workspace contains separate SQLite databases, temporary node chunks and logs. It is retained as raw experiment evidence. An earlier probe attempt failed while logging due to import path and is inconclusive; it is excluded from result tables. The successful retry used `integrity_probe_retry.db`.\n''',encoding='utf-8')
# File and structural validation.
for name in ['benchmark_results.csv','upload_results.csv','download_results.csv','fault_tolerance_results.csv','integrity_verification_results.csv','replication_results.csv','dataset_inventory.csv','test_file_manifest.csv']:
 with (R/name).open(newline='',encoding='utf-8-sig') as q: assert len(list(csv.reader(q)))>1,name
json.loads((R/'environment_details.json').read_text());
with zipfile.ZipFile(R/'experimental_results.xlsx') as z: assert z.testzip() is None and any(n.startswith('xl/worksheets/sheet') for n in z.namelist())
assert all(x['status']=='success' for x in b) and all(x['replica_restoration_success']=='pass' for x in f) and i[0]['status']=='PASS' and all(x['consistency_status']=='PASS' for x in r)
print(json.dumps({'transfer_trials':len(b),'upload_metrics':len(u),'download_metrics':len(d),'fault_trials':len(f),'integrity_cases':len(i),'replication_checks':len(r),'plots':[x.name for x in P.glob('*.png')],'xlsx_bytes':(R/'experimental_results.xlsx').stat().st_size,'validation':'PASS'},indent=2))
